 98 |     //====================================== HARVEST ========================================//
 99 | 
100 |     // Harvest, get payment, allocate, increase weight
101 |     function harvest(address synth) external returns(uint reward) {
102 |         address _member = msg.sender;
103 |         uint _weight;
104 |         address _token = iSYNTH(synth).TOKEN();
105 |         reward = calcCurrentReward(synth, _member);                     // In USDV
106 |         mapMemberSynth_lastTime[_member][synth] = block.timestamp;      // Reset time
107 |         if(iPOOLS(POOLS).isAsset(_token)){
108 |             iERC20(USDV).transfer(POOLS, reward); 
109 |             reward = iPOOLS(POOLS).mintSynth(USDV, _token, address(this));
110 |             _weight = iUTILS(UTILS()).calcValueInBase(_token, reward);
111 |         } else {
112 |             iERC20(VADER).transfer(POOLS, reward); 
113 |             reward = iPOOLS(POOLS).mintSynth(VADER, _token, address(this));
114 |             _weight = iROUTER(ROUTER).getUSDVAmount(iUTILS(UTILS()).calcValueInBase(_token, reward));
